def _refine(p):
    """Hill-climb: move or swap a model off the worst-KVPR GPU when it lowers max KVPR."""
    for _ in range(len(p) * 4):
        k = {g: _kvpr(p[g]) for g in p}
        src = max(p, key=lambda g: k[g])
        if k[src] <= 0:
            break
        cur = max(k.values())
        improved = False
        for m in list(p[src]):
            for dst in p:
                if dst == src:
                    continue
                dst_free = GPU_MEM_SIZE - sum(x.model_size for x in p[dst])
                # try plain move
                if m.model_size < dst_free:
                    p[src].remove(m)
                    p[dst].append(m)
                    nk = {g: _kvpr(p[g]) for g in p}
                    if max(nk.values()) < cur - 1e-12:
                        k, improved = nk, True
                        break
                    p[dst].remove(m)
                    p[src].append(m)
                # try swap with each model on dst
                for n in list(p[dst]):
                    if (m.model_size - n.model_size < dst_free and
                            n.model_size - m.model_size <
                            GPU_MEM_SIZE - sum(x.model_size for x in p[src])):
                        p[src].remove(m)
                        p[dst].remove(n)
                        p[src].append(n)
                        p[dst].append(m)
                        nk = {g: _kvpr(p[g]) for g in p}
                        if max(nk.values()) < cur - 1e-12:
                            k, improved = nk, True
                            break
                        p[dst].remove(m)
                        p[src].remove(n)
                        p[src].append(m)
                        p[dst].append(n)
                if improved:
                    break
            if improved:
                break
        if not improved:
            break
    return p
